            how: R`JS بتقيّم الشمال الأول. [[||]]: لو truthy رجّعه ووقف، غير كده رجّع اليمين. [[&&]]: لو falsy رجّعه ووقف، غير كده رجّع اليمين. والأولوية: [[&&]] قبل [[||]]، فـ [[a || b && c]] هي [[a || (b && c)]].`,
