          sol: R`مع [[Ali]] و [[alia]] و [[Sara]] وإيميلات [[ali@x.com]] و [[a_b@x.com]] و [[sara@y.org]] في PostgreSQL: الأول ← Ali، التاني ← Ali و alia، التالت ← Ali و alia، الرابع ← [[a_b@x.com]] بس، الخامس ← كل الإيميلات.`
